-- ==============================================================================
-- BỘ NẠP 11 DANH MỤC HIỆU ỨNG THỊ GIÁC CHUẨN QUỐC TẾ (157 EFFECT PRESETS)
-- LƯU TRỮ TRÊN SUPABASE TABLE `effect_presets`
-- ==============================================================================

-- Đảm bảo bảng effect_presets tồn tại và đầy đủ quyền RLS
CREATE TABLE IF NOT EXISTS public.effect_presets (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT DEFAULT ''::text,
    category TEXT NOT NULL,
    type TEXT DEFAULT 'effect'::text,
    tags TEXT[] DEFAULT '{}'::text[],
    preview_badge TEXT,
    config JSONB NOT NULL,
    is_system BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.effect_presets ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'effect_presets' AND policyname = 'Public select effect_presets') THEN
        CREATE POLICY "Public select effect_presets" ON public.effect_presets FOR SELECT TO public USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'effect_presets' AND policyname = 'Public insert effect_presets') THEN
        CREATE POLICY "Public insert effect_presets" ON public.effect_presets FOR INSERT TO public WITH CHECK (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'effect_presets' AND policyname = 'Public update effect_presets') THEN
        CREATE POLICY "Public update effect_presets" ON public.effect_presets FOR UPDATE TO public USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'effect_presets' AND policyname = 'Public delete effect_presets') THEN
        CREATE POLICY "Public delete effect_presets" ON public.effect_presets FOR DELETE TO public USING (true);
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_effect_presets_category ON public.effect_presets(category);
CREATE INDEX IF NOT EXISTS idx_effect_presets_is_system ON public.effect_presets(is_system);

-- CHÈN HOẶC CẬP NHẬT 157 PRESETS VÀO BẢNG effect_presets
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    category = EXCLUDED.category,
    tags = EXCLUDED.tags,
    preview_badge = EXCLUDED.preview_badge,
    config = EXCLUDED.config,
    is_system = EXCLUDED.is_system,
    updated_at = now();